'use client'

import Image from 'next/image'
import { motion } from 'framer-motion'
import { Heart, RotateCcw, ScrollText, Skull, Trophy } from 'lucide-react'
import { QUESTIONS } from '@/lib/game-data'
import { cn } from '@/lib/utils'
import { GameButton } from './game-button'
import type { SurvivalResult } from './survival-screen'

type EndScreenProps = {
  result: SurvivalResult
  onRetry: () => void
  onRestart: () => void
}

export function EndScreen({ result, onRetry, onRestart }: EndScreenProps) {
  const { won, lives, correct } = result
  const Icon = won ? Trophy : Skull

  return (
    <section className="relative flex h-full flex-col overflow-hidden" aria-labelledby="end-title">
      <Image
        src={won ? '/images/title.png' : '/images/war.png'}
        alt=""
        fill
        sizes="768px"
        className={cn('object-cover', won ? 'opacity-50' : 'opacity-35 grayscale-[60%]')}
      />
      <div className="absolute inset-0 bg-gradient-to-b from-background/50 via-background/60 to-background" />

      <div className="relative z-10 my-auto flex flex-col items-center gap-6 px-6 text-center">
        <motion.div
          initial={{ scale: 0, rotate: -20 }}
          animate={{ scale: 1, rotate: 0 }}
          transition={{ type: 'spring', stiffness: 200, damping: 14 }}
          className={cn(
            'flex size-20 items-center justify-center rounded-full border-2',
            won ? 'border-accent bg-accent/15 text-accent' : 'border-destructive bg-destructive/15 text-destructive',
          )}
        >
          <Icon className="size-10" aria-hidden="true" />
        </motion.div>

        <motion.div initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
          <h2 id="end-title" className="text-balance font-serif text-4xl font-bold text-foreground">
            {won ? 'Chúc mừng! Bạn đã sống sót' : 'Game Over'}
          </h2>
          <p className="mx-auto mt-3 max-w-sm text-pretty leading-relaxed text-muted-foreground">
            {won
              ? 'Ivan đã thoát khỏi khói lửa nhờ những kiến thức thu thập được trên con phố.'
              : 'Ivan đã gục ngã giữa làn đạn. Hãy ôn lại kiến thức và thử thêm lần nữa!'}
          </p>
        </motion.div>

        <motion.dl
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5 }}
          className="grid w-full max-w-sm grid-cols-2 gap-3"
        >
          <div className="rounded-md border border-border bg-card/80 p-4">
            <dt className="flex items-center justify-center gap-1.5 text-xs uppercase tracking-widest text-muted-foreground">
              <Heart className="size-3.5" aria-hidden="true" />
              Mạng còn lại
            </dt>
            <dd className="mt-1 font-serif text-3xl font-bold text-destructive">{lives}</dd>
          </div>
          <div className="rounded-md border border-border bg-card/80 p-4">
            <dt className="flex items-center justify-center gap-1.5 text-xs uppercase tracking-widest text-muted-foreground">
              <ScrollText className="size-3.5" aria-hidden="true" />
              Trả lời đúng
            </dt>
            <dd className="mt-1 font-serif text-3xl font-bold text-success">
              {correct}/{QUESTIONS.length}
            </dd>
          </div>
        </motion.dl>

        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.7 }}
          className="flex w-full max-w-sm flex-col gap-2"
        >
          <GameButton onClick={onRetry} className="w-full">
            <RotateCcw className="size-5" aria-hidden="true" />
            Chơi lại
          </GameButton>
          <GameButton onClick={onRestart} variant="secondary" className="w-full">
            Hành trình mới từ đầu
          </GameButton>
        </motion.div>
      </div>
    </section>
  )
}
